/* ── Ticker ── */
function Ticker() {
  const items = [
    { text: "POLICY-BOUND EXECUTION", icon: Lock },
    { text: "APPROVAL-GATED PUBLISHING", icon: CheckSquare },
    { text: "BRAND STANDARD ENFORCEMENT", icon: BookOpen },
    { text: "IMMUTABLE AUDIT EVIDENCE", icon: FileText },
    { text: "ROLE-SCOPED PERMISSIONS", icon: Users },
  ];
  return (
    <div className="border-y border-white/10 bg-[#111D2E] py-3 overflow-hidden">
      <div className="flex justify-center items-center gap-8 text-[10px] font-semibold tracking-widest text-white/[0.24] px-6 whitespace-nowrap">
        {items.map(({ text, icon: Icon }, i) => (
          <span key={i} className="flex items-center justify-center gap-2 h-[14.4px]">
            <Icon className="w-3 h-3 shrink-0 text-[#20E7F2]" />
            {text}
            {i < items.length - 1 && <span className="text-white/10 ml-6">|</span>}
          </span>
        ))}
      </div>
    </div>
  );
}

